// Phase 8: Event Loop Pooling & Optimization
// 이벤트 루프 풀링, 스레드 풀 동적 조정, 작업 스틸링 알고리즘
// ~200줄 (고성능 핵심)

pub use super::task_scheduler::{Task, TaskState, TaskPoller, WakeupEvent, WakeupReason};

// ========== Thread Pool Configuration ==========

#[derive(Clone, Debug)]
pub struct PoolConfig {
    pub min_threads: u32,
    pub max_threads: u32,
    pub queue_threshold: u32,  // 큐 크기 임계값 (스레드 생성 결정)
    pub idle_timeout_ms: u64,  // 유휴 스레드 제거 시간
    pub work_stealing_enabled: bool,
}

impl PoolConfig {
    pub fn default() -> Self {
        Self {
            min_threads: 4,
            max_threads: 32,
            queue_threshold: 128,
            idle_timeout_ms: 5000,
            work_stealing_enabled: true,
        }
    }
}

// ========== Worker Thread State ==========

#[derive(Clone, Debug, PartialEq)]
pub enum WorkerState {
    Active,      // 작업 중
    Idle,        // 유휴 상태
    Sleeping,    // 잠자는 상태
    Shutdown,    // 종료됨
}

pub struct WorkerThread {
    pub worker_id: u32,
    pub state: WorkerState,
    pub tasks_processed: u64,
    pub created_at: u64,
    pub last_active_at: u64,
}

impl WorkerThread {
    pub fn new(worker_id: u32, created_at: u64) -> Self {
        Self {
            worker_id,
            state: WorkerState::Idle,
            tasks_processed: 0,
            created_at,
            last_active_at: created_at,
        }
    }

    pub fn mark_active(&mut self, current_time: u64) {
        self.state = WorkerState::Active;
        self.last_active_at = current_time;
        self.tasks_processed += 1;
    }

    pub fn mark_idle(&mut self) {
        self.state = WorkerState::Idle;
    }

    pub fn is_idle(&self) -> bool {
        self.state == WorkerState::Idle
    }

    pub fn is_active(&self) -> bool {
        self.state == WorkerState::Active
    }

    pub fn idle_duration(&self, current_time: u64) -> u64 {
        if self.state == WorkerState::Idle {
            current_time - self.last_active_at
        } else {
            0
        }
    }
}

// ========== Work-Stealing Queue ==========

pub struct WorkStealingQueue {
    pub queue_id: u32,
    pub local_tasks: Vec<u32>,      // 이 큐의 로컬 작업
    pub stealer_count: u32,         // 다른 스레드에서 훔친 횟수
    pub max_size: usize,
}

impl WorkStealingQueue {
    pub fn new(queue_id: u32) -> Self {
        Self {
            queue_id,
            local_tasks: Vec::new(),
            stealer_count: 0,
            max_size: 256,
        }
    }

    pub fn push(&mut self, task_id: u32) -> bool {
        if self.local_tasks.len() >= self.max_size {
            return false;
        }
        self.local_tasks.push(task_id);
        true
    }

    pub fn pop_local(&mut self) -> Option<u32> {
        if self.local_tasks.is_empty() {
            None
        } else {
            Some(self.local_tasks.remove(0))
        }
    }

    pub fn steal_half(&mut self) -> Vec<u32> {
        let steal_count = self.local_tasks.len() / 2;
        if steal_count == 0 {
            return Vec::new();
        }

        let stolen: Vec<u32> = self.local_tasks.drain(0..steal_count).collect();
        self.stealer_count += 1;
        stolen
    }

    pub fn is_empty(&self) -> bool {
        self.local_tasks.is_empty()
    }

    pub fn len(&self) -> usize {
        self.local_tasks.len()
    }
}

// ========== Event Loop Pool Manager ==========

pub struct EventLoopPool {
    config: PoolConfig,
    workers: std::collections::HashMap<u32, WorkerThread>,
    work_queues: std::collections::HashMap<u32, WorkStealingQueue>,
    next_worker_id: u32,
    next_queue_id: u32,
    total_tasks_processed: u64,
    current_time: u64,
    last_balance_time: u64,
}

impl EventLoopPool {
    pub fn new(config: PoolConfig) -> Self {
        let mut pool = Self {
            config: config.clone(),
            workers: std::collections::HashMap::new(),
            work_queues: std::collections::HashMap::new(),
            next_worker_id: 0,
            next_queue_id: 0,
            total_tasks_processed: 0,
            current_time: 0,
            last_balance_time: 0,
        };

        // 초기 스레드 생성
        for _ in 0..config.min_threads {
            pool.create_worker();
        }

        pool
    }

    pub fn create_worker(&mut self) -> u32 {
        let worker_id = self.next_worker_id;
        self.next_worker_id += 1;

        let worker = WorkerThread::new(worker_id, self.current_time);
        self.workers.insert(worker_id, worker);

        let queue_id = self.next_queue_id;
        self.next_queue_id += 1;
        let queue = WorkStealingQueue::new(queue_id);
        self.work_queues.insert(queue_id, queue);

        worker_id
    }

    pub fn shutdown_worker(&mut self, worker_id: u32) -> bool {
        if let Some(worker) = self.workers.get_mut(&worker_id) {
            worker.state = WorkerState::Shutdown;
            return true;
        }
        false
    }

    pub fn submit_task(&mut self, worker_id: u32, task_id: u32) -> bool {
        // 라운드 로빈: 현재 활성 워커 찾기
        let target_worker = if let Some(worker) = self.workers.get(&worker_id) {
            if worker.state != WorkerState::Shutdown {
                worker_id
            } else {
                return false;
            }
        } else {
            return false;
        };

        // work queue 찾기
        if let Some(queue) = self.work_queues.values_mut().find(|q| q.queue_id == target_worker) {
            queue.push(task_id)
        } else {
            false
        }
    }

    pub fn get_next_task(&mut self, worker_id: u32) -> Option<u32> {
        // 1. 로컬 작업 먼저 가져오기
        if let Some(queue) = self.work_queues.values_mut().find(|q| q.queue_id == worker_id) {
            if let Some(task) = queue.pop_local() {
                return Some(task);
            }
        }

        // 2. Work stealing: 다른 큐에서 훔치기 (config.work_stealing_enabled)
        if self.config.work_stealing_enabled && !self.work_queues.is_empty() {
            let queues: Vec<u32> = self.work_queues.keys().cloned().collect();
            for queue_id in queues {
                if queue_id != worker_id {
                    if let Some(queue) = self.work_queues.get_mut(&queue_id) {
                        if !queue.is_empty() {
                            let stolen = queue.steal_half();
                            if !stolen.is_empty() {
                                return stolen.into_iter().next();
                            }
                        }
                    }
                }
            }
        }

        None
    }

    pub fn mark_worker_active(&mut self, worker_id: u32) -> bool {
        if let Some(worker) = self.workers.get_mut(&worker_id) {
            worker.mark_active(self.current_time);
            self.total_tasks_processed += 1;
            return true;
        }
        false
    }

    pub fn mark_worker_idle(&mut self, worker_id: u32) -> bool {
        if let Some(worker) = self.workers.get_mut(&worker_id) {
            worker.mark_idle();
            return true;
        }
        false
    }

    // 동적 스레드 풀 조정
    pub fn adjust_pool_size(&mut self) -> u32 {
        let mut created = 0u32;

        // 큐 크기 체크
        let total_queued: usize = self.work_queues.values().map(|q| q.len()).sum();

        // 큐가 크면 워커 추가
        if total_queued as u32 > self.config.queue_threshold {
            let current_workers = self.workers.len() as u32;
            if current_workers < self.config.max_threads {
                self.create_worker();
                created = 1;
            }
        }

        // 유휴 워커 제거
        let idle_workers: Vec<u32> = self.workers
            .iter()
            .filter(|(_, w)| {
                w.is_idle() && w.idle_duration(self.current_time) > self.config.idle_timeout_ms
            })
            .map(|(id, _)| *id)
            .collect();

        let current_workers = self.workers.len() as u32;
        for worker_id in idle_workers {
            if current_workers - created > self.config.min_threads {
                self.shutdown_worker(worker_id);
            }
        }

        created
    }

    pub fn advance_time(&mut self, delta: u64) {
        self.current_time += delta;

        // 주기적으로 풀 크기 조정 (100ms마다)
        if self.current_time - self.last_balance_time >= 100 {
            self.adjust_pool_size();
            self.last_balance_time = self.current_time;
        }
    }

    pub fn worker_count(&self) -> u32 {
        self.workers.len() as u32
    }

    pub fn active_worker_count(&self) -> u32 {
        self.workers.values().filter(|w| w.is_active()).count() as u32
    }

    pub fn idle_worker_count(&self) -> u32 {
        self.workers.values().filter(|w| w.is_idle()).count() as u32
    }

    pub fn queue_size(&self, worker_id: u32) -> usize {
        self.work_queues.values()
            .find(|q| q.queue_id == worker_id)
            .map(|q| q.len())
            .unwrap_or(0)
    }

    pub fn total_queued(&self) -> usize {
        self.work_queues.values().map(|q| q.len()).sum()
    }

    pub fn tasks_processed(&self) -> u64 {
        self.total_tasks_processed
    }

    pub fn work_stealing_stats(&self) -> u64 {
        self.work_queues.values().map(|q| q.stealer_count as u64).sum()
    }
}

