#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_e1_pool_creation() {
        let config = PoolConfig::default();
        let pool = EventLoopPool::new(config.clone());
        assert_eq!(pool.worker_count(), config.min_threads);
    }

    #[test]
    fn test_e2_task_submission() {
        let config = PoolConfig::default();
        let mut pool = EventLoopPool::new(config);

        assert!(pool.submit_task(0, 100));
        assert_eq!(pool.queue_size(0), 1);
    }

    #[test]
    fn test_e3_work_stealing() {
        let config = PoolConfig {
            min_threads: 2,
            work_stealing_enabled: true,
            ..PoolConfig::default()
        };
        let mut pool = EventLoopPool::new(config);

        // 워커 0에 작업 추가
        for i in 0..10 {
            pool.submit_task(0, i);
        }

        // 워커 1이 작업 가져오기
        if let Some(_task) = pool.get_next_task(1) {
            assert!(true); // work stealing 성공
        }
    }

    #[test]
    fn test_e4_dynamic_scaling() {
        let mut config = PoolConfig::default();
        config.queue_threshold = 5;
        let mut pool = EventLoopPool::new(config.clone());

        let initial_workers = pool.worker_count();

        // 큐를 많이 채우기
        for i in 0..200 {
            pool.submit_task(0, i);
        }

        // 풀 크기 조정
        pool.adjust_pool_size();

        assert!(pool.worker_count() > initial_workers);
    }

    #[test]
    fn test_e5_worker_lifecycle() {
        let config = PoolConfig::default();
        let mut pool = EventLoopPool::new(config);

        let worker_id = pool.create_worker();
        assert!(pool.workers.contains_key(&worker_id));

        pool.shutdown_worker(worker_id);
        assert_eq!(pool.workers.get(&worker_id).unwrap().state, WorkerState::Shutdown);
    }

    #[test]
    fn test_e6_idle_worker_cleanup() {
        let mut config = PoolConfig::default();
        config.min_threads = 2;
        config.idle_timeout_ms = 50;
        let mut pool = EventLoopPool::new(config);

        let initial_count = pool.worker_count();

        // 시간 경과
        for _ in 0..100 {
            pool.advance_time(10);
        }

        pool.adjust_pool_size();
        assert!(pool.worker_count() <= initial_count);
    }

    #[test]
    fn test_e7_worker_state_tracking() {
        let config = PoolConfig::default();
        let mut pool = EventLoopPool::new(config);

        pool.mark_worker_active(0);
        assert_eq!(pool.active_worker_count(), 1);

        pool.mark_worker_idle(0);
        assert_eq!(pool.idle_worker_count(), 1);
    }

    #[test]
    fn test_e8_queue_management() {
        let config = PoolConfig::default();
        let mut pool = EventLoopPool::new(config);

        for i in 0..50 {
            pool.submit_task(0, i);
        }

        assert_eq!(pool.queue_size(0), 50);
        assert_eq!(pool.total_queued(), 50);
    }

    #[test]
    fn test_e9_throughput_tracking() {
        let config = PoolConfig::default();
        let mut pool = EventLoopPool::new(config);

        for i in 0..100 {
            pool.mark_worker_active(i % 4);
        }

        assert_eq!(pool.tasks_processed(), 100);
    }

    #[test]
    fn test_e10_work_stealing_stats() {
        let config = PoolConfig {
            min_threads: 2,
            work_stealing_enabled: true,
            ..PoolConfig::default()
        };
        let mut pool = EventLoopPool::new(config);

        // 작업 추가 및 stealing
        for i in 0..20 {
            pool.submit_task(0, i);
        }

        // 워커 1에서 여러 번 steal 시도
        for _ in 0..5 {
            let _task = pool.get_next_task(1);
        }

        assert!(pool.work_stealing_stats() > 0);
    }
